package com.vandorlabs.client;

import com.google.gson.*;
import com.vandorlabs.programmer.*;
import com.vandorlabs.items.ModItems;
import java.nio.file.*;
import java.util.*;
import net.minecraft.item.*;
import net.minecraft.nbt.*;

/** Frozen actual released programmer decisions and physical operation results. */
public final class ProgrammerLegacyChecks {
 private static ItemStack sample(int kind,int company,int count,String type){if(kind==0)return ItemStack.EMPTY;ItemStack stack=new ItemStack(kind==1?ModItems.ACCESS_CARD:kind==2?ModItems.DATA_CHIP:net.minecraft.init.Items.STICK,count,company);NBTTagCompound tag=new NBTTagCompound();tag.setString("OpaqueInput","retained");tag.setIntArray("OpaqueArray",new int[]{3,17,29});if(kind==2&&type!=null){tag.setString("ChipType",type);if(type.equals("journal")){tag.setString("JournalTitle","Saved Journal");NBTTagList pages=new NBTTagList();pages.appendTag(new NBTTagString("Committed first page"));tag.setTag("JournalPages",pages);}if(type.equals("vehicle"))tag.setString("VehicleDesign","DEFERRED_OPAQUE");}stack.setTagCompound(tag);return stack;}
 private static JsonObject describe(ItemStack stack){JsonObject row=new JsonObject();row.addProperty("kind",stack.isEmpty()?0:stack.getItem()==ModItems.ACCESS_CARD?1:stack.getItem()==ModItems.DATA_CHIP?2:3);row.addProperty("count",stack.getCount());row.addProperty("company",stack.isEmpty()?0:stack.getMetadata());row.addProperty("master",ChipJournal.master(stack));return row;}
 private static JsonArray stacks(ProgrammerTile tile){JsonArray rows=new JsonArray();for(int slot=0;slot<3;slot++)rows.add(tile.getStackInSlot(slot).writeToNBT(new NBTTagCompound()).toString());return rows;}
 private static void install(ProgrammerTile tile,int slot,ItemStack stack){tile.setInventorySlotContents(slot,stack.copy());if(!stack.isEmpty())tile.getStackInSlot(slot).setCount(stack.getCount());}
 public static void main(String[] args)throws Exception {
  net.minecraft.init.Bootstrap.register();net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(ProgrammerTile.class,new net.minecraft.util.ResourceLocation("vandorlabs","data_chip_programmer"));net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(ModItems.ACCESS_CARD);net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(ModItems.DATA_CHIP);
  List<ItemStack> samples=new ArrayList<>();samples.add(ItemStack.EMPTY);samples.add(sample(3,0,1,null));for(int company=-1;company<=7;company++)for(int count:new int[]{1,2}){samples.add(sample(1,company,count,null));for(String type:new String[]{"master","journal","vehicle"})samples.add(sample(2,company,count,type));}
  JsonArray cases=new JsonArray();for(int m=0;m<samples.size();m++)for(int i=0;i<samples.size();i++)for(boolean occupied:new boolean[]{false,true})for(boolean journal:new boolean[]{false,true}){ProgrammerTile tile=new ProgrammerTile();install(tile,0,samples.get(m));install(tile,1,samples.get(i));if(occupied)install(tile,2,sample(1,2,1,null));JsonObject row=new JsonObject();row.add("master",describe(tile.getStackInSlot(0)));row.add("input",describe(tile.getStackInSlot(1)));row.addProperty("output",occupied);row.addProperty("journal",journal);row.addProperty("company",tile.company());row.addProperty("problem",tile.problem(journal));row.addProperty("canProgram",tile.canProgram(journal));row.addProperty("copyProblem",tile.copyProblem());for(int slot=0;slot<3;slot++)row.addProperty("valid"+slot,tile.isItemValidForSlot(slot,samples.get(i)));cases.add(row);}
  JsonArray operations=new JsonArray();for(int master=0;master<=6;master++)for(int kind=1;kind<=2;kind++)for(int company=0;company<=6;company++)for(boolean journal:new boolean[]{false,true})for(boolean copy:new boolean[]{false,true}){ProgrammerTile tile=new ProgrammerTile();if(master>0)install(tile,0,sample(2,master,1,"master"));install(tile,1,sample(kind,company,1,kind==2?"journal":null));if(copy)install(tile,2,sample(kind,(company+1)%7,1,null));tile.configure(journal,"Draft title",new String[]{"Draft first","Draft second"});JsonObject row=new JsonObject();row.addProperty("master",master);row.addProperty("kind",kind);row.addProperty("company",company);row.addProperty("journal",journal);row.addProperty("copy",copy);row.add("before",stacks(tile));row.addProperty("accepted",copy?tile.copyInput():tile.program());row.add("after",stacks(tile));row.addProperty("draftJournal",tile.journal);row.addProperty("draftTitle",tile.title);row.addProperty("status",tile.getProgrammerStatus().name());NBTTagCompound save=tile.writeToNBT(new NBTTagCompound());row.addProperty("writing",save.getInteger("Writing"));row.addProperty("complete",save.getInteger("Complete"));operations.add(row);}
  JsonObject root=new JsonObject();root.addProperty("schema",1);root.add("cases",cases);root.add("operations",operations);root.addProperty("fresh",new ProgrammerTile().writeToNBT(new NBTTagCompound()).toString());root.addProperty("titleLimit",ChipJournal.TITLE_LIMIT);root.addProperty("pageLimit",ChipJournal.PAGE_LIMIT);root.addProperty("pages",ChipJournal.MAX_PAGES);String body=root.toString();StringBuilder golden=new StringBuilder();for(byte value:java.security.MessageDigest.getInstance("SHA-256").digest(body.getBytes(java.nio.charset.StandardCharsets.UTF_8)))golden.append(String.format(Locale.ROOT,"%02x",value&255));if(cases.size()!=21904||operations.size()!=392||!golden.toString().equals("ef75c4ffecd2e1b4c7b4ce4fb50c4bbf6894dc8ccd51e3202e2342e7476a9ce2"))throw new AssertionError("Released programmer corpus changed: "+golden);root.addProperty("golden",golden.toString());Path output=Paths.get(System.getProperty("vandorlabs.programmerReference","build/test-artifacts/programmer-forge.json"));Files.createDirectories(output.toAbsolutePath().getParent());try(java.io.Writer writer=Files.newBufferedWriter(output)){new Gson().toJson(root,writer);}System.out.println("Actual programmer Source PASS cases="+cases.size()+" operations="+operations.size()+" golden="+golden);
 }
}
